/**
 * PatternDetail
 */
export type PatternDetail = {
    /**
     * Pattern Id
     */
    pattern_id: string;
    /**
     * Procedure Id
     */
    procedure_id: string;
    /**
     * Rule Id
     */
    rule_id: string;
    /**
     * Parent Id
     */
    parent_id: string | null;
    /**
     * Kind
     *
     * `rule`: every finding on a rule; `sub`: a named failure mode of it; `other`: findings that fit none.
     */
    kind: 'rule' | 'sub' | 'other';
    /**
     * Name
     */
    name: string;
    /**
     * Description
     */
    description: string | null;
    /**
     * Theme Id
     */
    theme_id: string | null;
    /**
     * Status
     */
    status: 'active' | 'retired';
    /**
     * Findings
     *
     * Findings in the window.
     */
    findings: number;
    /**
     * Sessions
     *
     * Sessions with a finding in the window.
     */
    sessions: number;
    /**
     * Total Findings
     *
     * All time.
     */
    total_findings: number;
    /**
     * Suppressed
     *
     * Suppressed findings in the window (not in `findings` or `sessions`).
     */
    suppressed: number;
    /**
     * First Seen
     */
    first_seen: string | null;
    /**
     * Last Seen
     */
    last_seen: string | null;
    /**
     * Theme Name
     */
    theme_name: string | null;
    /**
     * Examples
     */
    examples: Array<ExampleOut>;
    /**
     * Session Ids
     *
     * In the report: the most recent sessions (up to 12).
     */
    session_ids: Array<string>;
    /**
     * Need Attention Pct
     *
     * In the report: sessions in it that need attention / all that do.
     */
    need_attention_pct: number | null;
    /**
     * Clustered At
     *
     * Rule patterns: the last clustering. Sub-patterns: the last recluster that changed their findings materially.
     */
    clustered_at: string | null;
    /**
     * Its current verdict (its rule pattern's, when it has none of its own). On the patterns list and a pattern's page.
     */
    verdict: VerdictOut | null;
    /**
     * Review State
     *
     * On the patterns list and a pattern's page. `needs_review`: no verdict, a verdict carried over by a recluster, or one older than a recluster that changed its findings. `open`: real or sop_wrong with no suggestion applied. `fixing`: a suggestion applied (draft or pull request), waiting for its release to be live and for enough sessions on it. `fixed`: no findings in 10 sessions on that release or later. `regressed`: findings came back on such sessions. `closed`: acceptable or checker_wrong.
     */
    review_state: 'needs_review' | 'open' | 'fixing' | 'fixed' | 'regressed' | 'closed' | null;
    /**
     * Review Reason
     *
     * Why it needs review: `no_verdict`; `carried_over` (by a recluster); `reclustered` (its findings changed since the verdict); `reworded` (the rule was reworded after an acceptable or checker_wrong verdict); `came_back` (regressed). Null otherwise.
     */
    review_reason: 'no_verdict' | 'carried_over' | 'reclustered' | 'reworded' | 'came_back' | null;
    /**
     * Review Note
     */
    review_note: string | null;
    rule: RuleRef;
    /**
     * Sub Patterns
     */
    sub_patterns: Array<PatternOut>;
    /**
     * Verdict History
     *
     * Its own verdicts, newest first.
     */
    verdict_history: Array<VerdictOut>;
    /**
     * Suppressed Count
     *
     * Suppressed findings, all time.
     */
    suppressed_count: number;
    /**
     * Suggestions
     *
     * Newest first.
     */
    suggestions: Array<SuggestionSummary>;
    /**
     * Fix Release
     *
     * The release with the applied edit, once there is one.
     */
    fix_release: number | null;
    /**
     * Fix Sessions
     *
     * Fixing (release live) and fixed: sessions checked on the procedure on the fix's release or later.
     */
    fix_sessions: number | null;
    /**
     * Fix Sessions Needed
     *
     * With fix_sessions: how many it takes, with no finding in the pattern, to count as fixed.
     */
    fix_sessions_needed: number | null;
};

