    /**
     * Description
     */
    description: string | null;
    /**
     * Theme Id
     */
    theme_id: string | null;
    /**
     * Theme Name
     */
    theme_name: string | null;
    /**
     * Status
     */
    status: 'active' | 'retired';
    /**
     * Findings
     *
     * All time.
     */
    findings: number;
    /**
     * Sessions
     *
     * All time.
     */
    sessions: number;
    /**
     * First Seen
     */
    first_seen: string | null;
    /**
     * Last Seen
     */
    last_seen: string | null;
