/**
 * SuggestionDetail
 */
export type SuggestionDetail = {
    /**
     * Suggestion Id
     */
    suggestion_id: string;
    /**
     * Pattern Id
     */
    pattern_id: string;
    /**
     * Pattern Name
     */
    pattern_name: string | null;
    /**
     * Procedure Id
     */
    procedure_id: string;
    /**
     * Rule Id
     */
    rule_id: string;
    /**
     * Block Id
     *
     * The block the edit is to: the procedure.
     */
    block_id: string;
    /**
     * Status
     *
     * `generating` until the model and sopc are done; then `proposed` or `failed`. A proposal becomes `applied` (a draft edit), `pr_open` (a pull request; then `merged`, or `dismissed` when it's closed) or `dismissed`.
     */
    status: 'generating' | 'proposed' | 'applied' | 'dismissed' | 'pr_open' | 'merged' | 'failed';
    /**
     * Rationale
     */
    rationale: string | null;
    /**
     * Error
     *
     * Why it failed: sopc's issues with the last proposal, or the model's error.
     */
    error: string | null;
    /**
     * Pr Url
     */
    pr_url: string | null;
    /**
     * Created At
     */
    created_at: string;
    /**
     * Updated At
     */
    updated_at: string;
    /**
     * Applied At
     *
     * When it was saved as a draft edit.
     */
    applied_at: string | null;
    /**
     * Pr Opened At
     *
     * When its pull request was opened.
     */
    pr_opened_at: string | null;
    /**
     * Merged At
     *
     * When sopops saw its pull request merged (checked every 15 minutes, and when it's read).
     */
    merged_at: string | null;
    /**
     * Released In
     *
     * The first release whose file is the suggested text (for a repo: after the merge is pulled and published).
     */
    released_in: number | null;
    /**
     * Released At
     *
     * When that release was published.
     */
    released_at: string | null;
    /**
     * Freshness
     *
     * A proposed suggestion against the procedure's file now: `current` (unchanged since it was written), `merges` (changed; the edit merges in and the result compiles) or `conflict` (the same lines were changed, or the merged file doesn't compile: apply is refused; rewrite it). None for any other status.
     */
    freshness: 'current' | 'merges' | 'conflict' | null;
    /**
     * Path
     *
     * The procedure's file.
     */
    path: string | null;
    /**
     * Base Version
     *
     * The file's version it was made from; applying needs head to still be it.
     */
    base_version: number | null;
    /**
     * Old Text
     */
    old_text: string | null;
    /**
     * New Text
     */
    new_text: string | null;
    plan: SuggestionPlan | null;
    /**
     * Note
     *
     * Why it was dismissed.
     */
    note: string | null;
    /**
     * Reviewer
     */
    reviewer: string | null;
    /**
     * Attempts
     *
     * Model proposals made (a proposal that doesn't compile is sent back once).
     */
    attempts: number;
    /**
     * Model
     */
    model: string | null;
    /**
     * Prompt Version
     */
    prompt_version: string | null;
    pattern: SuggestionPattern | null;
    /**
     * The verdict it was made for.
     */
    verdict: VerdictOut | null;
    /**
     * Merged Into Version
     *
     * Applied into this version of the file, merged with changes made since it was written.
     */
    merged_into_version: number | null;
    /**
     * Rewrite Of
     *
     * The suggestion this one rewrites against the current text.
     */
    rewrite_of: string | null;
    /**
     * Rewritten As
     *
     * The suggestion that rewrote this one.
     */
    rewritten_as: string | null;
    /**
     * A proposed suggestion: how the procedure's file changed since it was written, and how the edit fits it now.
     */
    since_written: SinceWritten | null;
};

