export type ListSessionsData = {
    body?: never;
    path: {
        /**
         * Workspace
         */
        workspace: string;
    };
    query?: {
        /**
         * Agent
         *
         * sopc agent id, or the agent as sent.
         */
        agent?: string | null;
        /**
         * Channel
         */
        channel?: 'voice' | 'text' | null;
        /**
         * Status
         */
        status?: 'open' | 'received' | 'routed' | 'checked' | 'excluded' | 'incomplete' | 'failed' | null;
        /**
         * Result
         *
         * The session's worst procedure result.
         */
        result?: 'deviated' | 'partial' | 'followed' | 'not_measurable' | null;
        /**
         * Platform
         */
        platform?: 'livekit' | 'elevenlabs' | 'vapi' | 'otel' | 'import' | 'api' | null;
        /**
         * Since
         *
         * Started at or after.
         */
        since?: string | null;
        /**
         * Until
         *
         * Started before.
         */
        until?: string | null;
        /**
         * Cursor
         *
         * `next_cursor` from the previous page.
         */
        cursor?: string | null;
        /**
         * Limit
         */
        limit?: number;
        /**
         * Release
         *
         * The release the session ran.
         */
        release?: number | null;
        /**
         * Procedure
         *
         * Sessions the router considered this procedure for; each item then carries `procedure_check`.
         */
        procedure?: string | null;
        /**
         * Procedure Result
         *
         * With a procedure check with this result (of `procedure`, if given).
         */
        procedure_result?: 'deviated' | 'partial' | 'followed' | 'not_measurable' | null;
        /**
         * Rule
         *
         * With a result on this rule id.
         */
        rule?: string | null;
        /**
         * Rule Status
         *
         * With `rule`: only these statuses (e.g. skipped); alone: a result on any rule with one of them.
         */
        rule_status?: Array<'done' | 'out_of_order' | 'skipped' | 'not_reached' | 'not_applicable' | 'violated' | 'ok' | 'present' | 'unheeded' | 'absent'> | null;
        /**
         * Pattern
         *
         * With a finding in this pattern (a rule pattern includes its sub-patterns).
         */
        pattern?: string | null;
        /**
         * Theme
         *
         * With a finding in a pattern of this theme.
         */
        theme?: string | null;
        /**
         * Finding
         *
         * With (true) or without (false) any finding.
         */
        finding?: boolean | null;
        /**
         * Eligible
         *
         * Only sessions Insights rates (checked or incomplete, with a result); false: the others.
         */
        eligible?: boolean | null;
        /**
         * Suppressed
         *
         * How `rule`/`rule_status`, `pattern`, `theme` and `finding` treat suppressed findings: false leaves them out (what Insights counts), true matches only them; unset, both.
         */
        suppressed?: boolean | null;
    };
    url: '/v1/workspaces/{workspace}/sessions';
};

